INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('force_arrow_translate_animation_not_supported', 'drawForceArrow never read spec.animation — a "carry a vector parallel to itself" beat (rigid translate) was unbuildable in PCPL', 'MAJOR', 'peter_parker:renderer_primitives', 'FIXED 2026-07-24. drawBody() implements spec.animation.type === "translate" (a smooth one-shot slide by (dx_px, dy_px) over duration_sec + optional delay_sec, ease-out cubic, clamped at the end — parametric_renderer.ts ~line 1099), but drawForceArrow() never read spec.animation at all — authoring animation:{type:"translate",...} on a force_arrow silently no-op''d. Surfaced by vector_addition_law STATE_2 (the PRIMARY-aha state, delta cue "Carry B — tail on head"): with no renderer support, the JSON had to fake the carry using two arrows (leg_B_ghost floating at a fixed point, disappear_at_ms 2600; leg_B_dock anchored + appear_at_ms 2600 grow-in) — sound-off the student sees a blink-out/blink-in, not a rigid parallel carry, even though "carry" is the exact word in both the delta cue and the narration.', 'drawForceArrow now reads spec.animation.type === "translate" with the IDENTICAL easing/delay/duration/clamp conventions as drawBody''s translate branch (same timing vocabulary across primitive types, pure function of PM_simClockMs per Rule 36). The offset applies ONLY to the already-resolved origin (x1/y1) — the arrow''s magnitude/direction (dx/dy, derived solely from force.vector/scale/gate.alpha) are never touched, so length and heading stay visibly frozen while the arrow rigidly slides (the entire pedagogical point of a parallel-carry beat). Because the offset is applied to the caller-resolved `origin` parameter, it composes with every existing origin-resolution path (literal from, origin_body_id, anchor_to, *_expr) without needing per-path changes. deriveStateMeta.ts''s pcplSceneRevealMs() needed NO change — it already scans every scene_composition primitive generically for animation.delay_sec/duration_sec regardless of primitive type, so a force_arrow translate is automatically registered for reveal-hold classification the same way a body translate already is. Any FUTURE force_arrow animation type must be added the same way: read spec.animation inside drawForceArrow, offset origin only (never the force-vector-derived shaft), reuse existing timing field names — never invent a second animation vocabulary for arrows vs bodies.', 'js_eval', 'For a force_arrow spec with animation:{type:"translate", delay_sec:D, duration_sec:T, dx_px, dy_px}: at PM_simClockMs < D*1000, the drawn origin equals the pre-animation resolved origin (offset 0,0); at PM_simClockMs === (D+T/2)*1000, offset equals (dx_px,dy_px) scaled by the ease-out-cubic value at t=0.5 (1-0.5^3=0.875); at PM_simClockMs >= (D+T)*1000, offset equals exactly (dx_px,dy_px), clamped (no overshoot past). At every one of those three times, the arrow''s length (hypot(dx,dy) of the SHAFT, i.e. tip-minus-origin) and heading (atan2(dy,dx) of the shaft) must be numerically identical — only the origin/tip pair translates, never the shaft vector. Regression guard: src/lib/renderers/__tests__/parametric_renderer.test.ts "force_arrow translate (2026-07-24)" describe block (string-presence: drawForceArrow reads spec.animation.type===translate, x1/y1 pick up arrowAnimDx/Dy, dx/dy stay derived from force.vector alone).', 'FIXED', ARRAY['vector_addition_law'], ARRAY['src/lib/renderers/parametric_renderer.ts', 'src/lib/renderers/__tests__/parametric_renderer.test.ts'], 'session_2026-07-24_force_arrow_translate_animation', 'incident')
